1	package scan
2	
3	import (
4		"log"
5		"os"
6		"path/filepath"
7		"regexp"
8		"strings"
9	
10		"github.com/anthnel/devdesk/internal/k8s"
11	)
12	
13	// Why a KSV-0104 finding fired (DEVDESK-686, S-01). Trivy words the finding the
14	// same for an explicit Unconfined and for a missing seccomp profile, and
15	// points at the container's block rather than at the line that says
16	// Unconfined, so neither the message nor the span tells the two apart. The
17	// manifest is read again at scan time, the way the Kubernetes fixes read it
18	// (§3.80): the document at the reported line, the container by its name inside
19	// the reported lines.
20	const (
21		SeccompUnconfined = "unconfined"
22		SeccompAbsent     = "absent"
23	)
24	
25	// seccompContainer is how KSV-0104 names its container: lower case and double
26	// quotes, unlike the other KSV rules ("Container 'api' of …").
27	var seccompContainer = regexp.MustCompile(`container "([^"]+)"`)
28	
29	// isSeccompRule reports whether id is KSV-0104, in any of the three spellings
30	// Trivy and the cache have used. This package cannot import remediation, where
31	// RuleKey lives.
32	func isSeccompRule(id string) bool {
33		id = strings.ReplaceAll(strings.TrimPrefix(strings.ToUpper(strings.TrimSpace(id)), "AVD-"), "-", "")
34		return id == "KSV0104" || id == "KSV104"
35	}
36	
37	// annotateSeccomp sets SeccompOrigin on the kubernetes KSV-0104 findings of a
38	// directory scan, reading each file once. It never fails the scan: whatever it
39	// cannot confirm leaves the origin empty, which reads as "unknown".
40	func annotateSeccomp(root string, findings []Finding) {
41		byFile := map[string][]int{}
42		for i, f := range findings {
43			if f.Source == SourceTrivyMisconfig && f.IaCType == "kubernetes" && isSeccompRule(f.ID) {
44				byFile[f.File] = append(byFile[f.File], i)
45			}
46		}
47		if len(byFile) == 0 {
48			return
49		}
50		dir, err := os.OpenRoot(root)
51		if err != nil {
52			log.Printf("WARN [scan] seccomp origin: cannot open %s: %v", root, err)
53			return
54		}
55		defer func() { _ = dir.Close() }()
56	
57		for file, indexes := range byFile {
58			name := filepath.FromSlash(file)
59			if !filepath.IsLocal(name) {
60				log.Printf("WARN [scan] seccomp origin: %s is outside the scanned directory", file)
61				continue
62			}
63			content, err := k8s.ReadManifestIn(dir, name)
64			if err != nil {
65				log.Printf("WARN [scan] seccomp origin: cannot read %s: %v", file, err)
66				continue
67			}
68			for _, i := range indexes {
69				findings[i].SeccompOrigin = seccompOrigin(content, findings[i])
70			}
71		}
72	}
73	
74	// seccompOrigin classifies one KSV-0104 finding from the manifest's bytes:
75	// SeccompUnconfined, SeccompAbsent, or "" when it cannot tell (the file
76	// changed since Trivy read it, the container is not at the reported lines, a
77	// profile is now set).
78	func seccompOrigin(content []byte, f Finding) string {
79		m := seccompContainer.FindStringSubmatch(f.Message)
80		if m == nil || f.Line <= 0 {
81			return ""
82		}
83		doc, ok := k8s.DocumentAt(content, f.Line)
84		if !ok {
85			return ""
86		}
87		for _, spec := range k8s.PodSpecs(doc) {
88			for _, c := range spec.Containers {
89				if k8s.Scalar(c, "name") != m[1] {
90					continue
91				}
92				if f.EndLine > 0 && (c.Line < f.Line || c.Line > f.EndLine) {
93					continue
94				}
95				switch t := k8s.SeccompType(doc, spec, c); {
96				case strings.EqualFold(t, "unconfined"):
97					return SeccompUnconfined
98				case t == "":
99					return SeccompAbsent
100				}
101				return ""
102			}
103		}
104		return ""
105	}
106

1	package security
2	
3	import (
4		"fmt"
5		"strconv"
6	
7		tea "charm.land/bubbletea/v2"
8	
9		"github.com/anthnel/devdesk/internal/config"
10		"github.com/anthnel/devdesk/internal/remediation"
11		"github.com/anthnel/devdesk/internal/scan"
12		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
13		"github.com/anthnel/devdesk/internal/ui/shortcut"
14		"github.com/anthnel/devdesk/internal/ui/theme"
15	)
16	
17	// The Pod Security profile on the Misconfigurations tab (DEVDESK-686, S-01):
18	// a label on every Pod Security finding, and a filter that hides what the
19	// target profile does not require. The label shows under every setting; the
20	// filter is off when the tab opens and p is greyed under all.
21	
22	// pssFilterKey toggles the Pod Security filter.
23	const pssFilterKey = "p"
24	
25	// pssToken is the filter's label in the bar.
26	const pssToken = "REDACTED"
27	
28	// pssLabelSeparator sits between the label and the title in the Title cell.
29	const pssLabelSeparator = " · "
30	
31	// Why `p` is greyed (Rule 130).
32	const (
33		reasonPSSNotMisconfigTab = "The Pod Security filter belongs to the Misconfigurations tab"
34		reasonPSSAll             = "scan.pss_profile is all: choose baseline or restricted in the configuration"
35		reasonPSSInvalid         = "scan.pss_profile %q is not all, baseline or restricted, so all is used"
36	)
37	
38	// pssFromTrivySuffix says the profile was read in Trivy's references for a rule
39	// the table does not know.
40	const pssFromTrivySuffix = " (from Trivy, no fix)"
41	
42	// findingTokens are the severity tokens plus the Pod Security one.
43	func findingTokens() []sharedcomponents.FilterToken {
44		return append(severityTokens(), sharedcomponents.FilterToken{Label: pssToken})
45	}
46	
47	// matchesFinding is the findings table's token match for a target profile
48	// ("all", "baseline" or "restricted"). The severity tokens and the Pod Security
49	// one are separate questions: a finding must pass both.
50	func matchesFinding(target string) func(scan.Finding, map[string]bool) bool {
51		return func(f scan.Finding, active map[string]bool) bool {
52			if !matchesSeverity(f, active) {
53				return false
54			}
55			return !active[pssToken] || !pssHides(f, target)
56		}
57	}
58	
59	// pssHides reports whether the target profile leaves the finding out: it is a
60	// Pod Security finding the target does not require. Under all, or a value that
61	// is not a profile, nothing is hidden.
62	func pssHides(f scan.Finding, target string) bool {
63		t := remediation.Profile(target)
64		if t != remediation.ProfileBaseline && t != remediation.ProfileRestricted {
65			return false
66		}
67		pss, ok := remediation.PodSecurity(f)
68		return ok && !t.Covers(pss.Profile)
69	}
70	
71	// pssLabel is the label a finding carries, or "" outside Pod Security.
72	func pssLabel(f scan.Finding) string {
73		pss, ok := remediation.PodSecurity(f)
74		if !ok {
75			return ""
76		}
77		if pss.FromTrivy {
78			return string(pss.Profile) + pssFromTrivySuffix
79		}
80		return string(pss.Profile)
81	}
82	
83	// titleWithLabel is the Title cell: the title, preceded by the label when the
84	// finding has one. Plain text (Rule 122).
85	func titleWithLabel(f scan.Finding) string {
86		if label := pssLabel(f); label != "" {
87			return label + pssLabelSeparator + f.Title
88		}
89		return f.Title
90	}
91	
92	// canTogglePSS says whether `p` applies here.
93	func (m Model) canTogglePSS() shortcut.Availability {
94		switch {
95		case m.activeTab != TabMisconfig:
96			return shortcut.Unavailable(reasonPSSNotMisconfigTab)
97		case !m.config.Scan.PSSProfileValid():
98			return shortcut.Unavailable(m.invalidPSSReason())
99		case m.config.Scan.EffectivePSSProfile() == config.PSSProfileAll:
100			return shortcut.Unavailable(reasonPSSAll)
101		}
102		return shortcut.Availability{}
103	}
104	
105	func (m Model) invalidPSSReason() string {
106		return fmt.Sprintf(reasonPSSInvalid, m.config.Scan.PSSProfile)
107	}
108	
109	// togglePSS flips the Pod Security filter, or says why it cannot (Rule 130).
110	func (m Model) togglePSS() (tea.Model, tea.Cmd) {
111		if a := m.canTogglePSS(); !a.Enabled() {
112			return m, m.footer.Warn(a.Reason)
113		}
114		m.findingsTable.SetTokenActive(pssToken, !m.findingsTable.IsTokenActive(pssToken))
115		m.findingsTable.GotoTop()
116		return m, nil
117	}
118	
119	// enterPSSTab warns, on entering the Misconfigurations tab, that the profile in
120	// the configuration is not one DevDesk knows. Nothing is hidden meanwhile.
121	func (m *Model) enterPSSTab() tea.Cmd {
122		if m.activeTab != TabMisconfig || m.config.Scan.PSSProfileValid() {
123			return nil
124		}
125		return m.footer.Warn(m.invalidPSSReason())
126	}
127	
128	// pssHeader is the header entry of the Misconfigurations tab: the profile, the
129	// state of the filter, and what it hides. Absent under all and under a value
130	// that is not in force.
131	func (m Model) pssHeader() (shortcut.HeaderInfo, bool) {
132		if (m.state != StateResults && m.state != StateDetails) || m.result == nil || m.activeTab != TabMisconfig {
133			return shortcut.HeaderInfo{}, false
134		}
135		target := m.config.Scan.EffectivePSSProfile()
136		if target == config.PSSProfileAll {
137			return shortcut.HeaderInfo{}, false
138		}
139		value := target + " · filter off"
140		if m.findingsTable.IsTokenActive(pssToken) {
141			// Counted over the whole tab, before the severity filter and the search:
142			// those narrow the list, they do not make Trivy's answer any shorter.
143			hidden, shown := pssCounts(m.filterFindingsByTab(), remediation.Profile(target))
144			value = target + " · filter on · " + strconv.Itoa(hidden) + " hidden"
145			if shown == 0 {
146				// Said as what Trivy did, never as compliance.
147				value += " · no violation detected by Trivy for " + target
148			}
149		}
150		return shortcut.HeaderInfo{Key: "Pod Security", Value: value, Style: theme.HeaderValueStyle}, true
151	}
152	
153	// pssCounts says how many Pod Security findings the target profile hides, and
154	// how many it keeps.
155	func pssCounts(findings []scan.Finding, target remediation.Profile) (hidden, shownPSS int) {
156		for _, f := range findings {
157			pss, ok := remediation.PodSecurity(f)
158			switch {
159			case !ok:
160			case target.Covers(pss.Profile):
161				shownPSS++
162			default:
163				hidden++
164			}
165		}
166		return hidden, shownPSS
167	}
168

1	package k8s
2	
3	import (
4		"strings"
5	
6		"gopkg.in/yaml.v3"
7	)
8	
9	// PodSpec is one pod spec of a workload and its containers (containers,
10	// initContainers and ephemeralContainers).
11	type PodSpec struct {
12		Spec       *yaml.Node
13		Containers []*yaml.Node
14	}
15	
16	// seccompAnnotationPrefix is the pre-1.19 way to set a container's seccomp
17	// profile. Trivy still reads it, so the type in force has to as well.
18	const seccompAnnotationPrefix = "container.seccomp.security.alpha.kubernetes.io/"
19	
20	// podSpecPaths is where each workload kind keeps its pod spec, as the keys to
21	// follow from the document's root. The kind decides, not a search for a
22	// "containers" key: a YAML anchor or an unrelated field named that way is not
23	// a pod spec.
24	var podSpecPaths = map[string][]string{
25		"Pod":                   {"spec"},
26		"PodTemplate":           {"template", "spec"},
27		"Deployment":            {"spec", "template", "spec"},
28		"StatefulSet":           {"spec", "template", "spec"},
29		"DaemonSet":             {"spec", "template", "spec"},
30		"ReplicaSet":            {"spec", "template", "spec"},
31		"ReplicationController": {"spec", "template", "spec"},
32		"Job":                   {"spec", "template", "spec"},
33		"CronJob":               {"spec", "jobTemplate", "spec", "template", "spec"},
34	}
35	
36	// PodSpecs returns every pod spec of a workload document, aliases resolved.
37	// A document that is not a workload has none.
38	func PodSpecs(doc *yaml.Node) []PodSpec {
39		path, ok := podSpecPaths[Scalar(doc, "kind")]
40		if !ok {
41			return nil
42		}
43		spec := follow(doc, path)
44		if spec == nil || spec.Kind != yaml.MappingNode {
45			return nil
46		}
47		ps := PodSpec{Spec: spec}
48		for _, key := range []string{"containers", "initContainers", "ephemeralContainers"} {
49			_, list, ok := Entry(spec, key)
50			if !ok || list.Kind != yaml.SequenceNode {
51				continue
52			}
53			for _, c := range list.Content {
54				if c = resolveAlias(c); c.Kind == yaml.MappingNode {
55					ps.Containers = append(ps.Containers, c)
56				}
57			}
58		}
59		return []PodSpec{ps}
60	}
61	
62	// SeccompType is the profile type in force for container, in Trivy's order:
63	// the container's securityContext, then the pod's, then the container
64	// annotation. Empty when none is set. doc is the workload the pod spec belongs
65	// to: the annotation sits on the metadata next to the pod spec, which the spec
66	// node alone does not reach.
67	func SeccompType(doc *yaml.Node, spec PodSpec, container *yaml.Node) string {
68		if t := seccompTypeOf(container); t != "" {
69			return t
70		}
71		if t := seccompTypeOf(spec.Spec); t != "" {
72			return t
73		}
74		path, ok := podSpecPaths[Scalar(doc, "kind")]
75		if !ok {
76			return ""
77		}
78		// The pod's metadata is the sibling of the pod spec: "spec" becomes "metadata".
79		meta := append(append([]string(nil), path[:len(path)-1]...), "metadata")
80		podMeta := follow(doc, meta)
81		if podMeta == nil {
82			return ""
83		}
84		_, annotations, ok := Entry(podMeta, "annotations")
85		if !ok {
86			return ""
87		}
88		return Scalar(annotations, seccompAnnotationPrefix+Scalar(container, "name"))
89	}
90	
91	// seccompTypeOf reads securityContext.seccompProfile.type of a container or a
92	// pod spec.
93	func seccompTypeOf(n *yaml.Node) string {
94		if n == nil {
95			return ""
96		}
97		_, sc, ok := Entry(n, "securityContext")
98		if !ok {
99			return ""
100		}
101		_, profile, ok := Entry(sc, "seccompProfile")
102		if !ok {
103			return ""
104		}
105		return strings.TrimSpace(Scalar(profile, "type"))
106	}
107	
108	// follow walks keys down from n, resolving aliases, and returns nil when the
109	// path is not there.
110	func follow(n *yaml.Node, keys []string) *yaml.Node {
111		for _, key := range keys {
112			if n == nil {
113				return nil
114			}
115			_, v, ok := Entry(n, key)
116			if !ok {
117				return nil
118			}
119			n = v
120		}
121		return n
122	}
123

diff --git i/internal/config/config.go w/internal/config/config.go
index 88b0ef67..e081e49a 100644
--- i/internal/config/config.go
+++ w/internal/config/config.go
@@ -483,6 +483,12 @@ type ScanConfig struct {
 	// "same-line" (the default) or "next-major". See base_image_track.go.
 	BaseImageTrack string `yaml:"base_image_track"`

+	// PSSProfile is the Pod Security profile this context aims at: "all",
+	// "baseline" or "restricted". Never defaulted in memory: empty reads as
+	// "all", so a file written before the key existed is not rewritten with it.
+	// See pss_profile.go.
+	PSSProfile string `yaml:"pss_profile,omitempty"`
+
 	// ImageVerification is "on" (the default) or "off": whether image
 	// signatures are verified. Per context, unlike the policy in
 	// ~/.devdesk/trust.yaml — whom to trust is a fact about the world, whether
@@ -619,6 +625,9 @@ func applyDefaults(cfg *Config) error {
 	if cfg.Scan.BaseImageTrack == "" {
 		cfg.Scan.BaseImageTrack = BaseImageTrackSameLine
 	}
+	// scan.pss_profile is not defaulted: empty reads as all, so a file written
+	// before the key existed is not rewritten with it.
+	warnInvalidPSSProfile(cfg.Scan)
 	if cfg.Scan.ImageVerification == "" {
 		cfg.Scan.ImageVerification = ImageVerificationOn
 	}
diff --git i/internal/k8s/discover.go w/internal/k8s/discover.go
index 86affbfd..361713bd 100644
--- i/internal/k8s/discover.go
+++ w/internal/k8s/discover.go
@@ -268,3 +268,16 @@ func readBounded(path string) ([]byte, error) {
 	}
 	return os.ReadFile(path) //nolint:gosec // a file of the repository being scanned
 }
+
+// ReadManifestIn reads a file of root, which it cannot leave (a ".." or a
+// symlink pointing out is refused), under the same size bound as readBounded.
+func ReadManifestIn(root *os.Root, name string) ([]byte, error) {
+	info, err := root.Stat(name)
+	if err != nil {
