1	package k8s
2	
3	import (
4		"strings"
5	
6		"gopkg.in/yaml.v3"
7	)
8	
9	// PodSpec is one pod spec of a workload and its containers (containers,
10	// initContainers and ephemeralContainers).
11	type PodSpec struct {
12		Spec       *yaml.Node
13		Containers []*yaml.Node
14	}
15	
16	// seccompAnnotationPrefix is the pre-1.19 way to set a container's seccomp
17	// profile. Trivy still reads it, so the type in force has to as well.
18	const seccompAnnotationPrefix = "container.seccomp.security.alpha.kubernetes.io/"
19	
20	// podSpecPaths is where each workload kind keeps its pod spec, as the keys to
21	// follow from the document's root. The kind decides, not a search for a
22	// "containers" key: a YAML anchor or an unrelated field named that way is not
23	// a pod spec.
24	var podSpecPaths = map[string][]string{
25		"Pod":                   {"spec"},
26		"PodTemplate":           {"template", "spec"},
27		"Deployment":            {"spec", "template", "spec"},
28		"StatefulSet":           {"spec", "template", "spec"},
29		"DaemonSet":             {"spec", "template", "spec"},
30		"ReplicaSet":            {"spec", "template", "spec"},
31		"ReplicationController": {"spec", "template", "spec"},
32		"Job":                   {"spec", "template", "spec"},
33		"CronJob":               {"spec", "jobTemplate", "spec", "template", "spec"},
34	}
35	
36	// PodSpecs returns every pod spec of a workload document, aliases resolved.
37	// A document that is not a workload has none.
38	func PodSpecs(doc *yaml.Node) []PodSpec {
39		path, ok := podSpecPaths[Scalar(doc, "kind")]
40		if !ok {
41			return nil
42		}
43		spec := follow(doc, path)
44		if spec == nil || spec.Kind != yaml.MappingNode {
45			return nil
46		}
47		ps := PodSpec{Spec: spec}
48		for _, key := range []string{"containers", "initContainers", "ephemeralContainers"} {
49			_, list, ok := Entry(spec, key)
50			if !ok || list.Kind != yaml.SequenceNode {
51				continue
52			}
53			for _, c := range list.Content {
54				if c = resolveAlias(c); c.Kind == yaml.MappingNode {
55					ps.Containers = append(ps.Containers, c)
56				}
57			}
58		}
59		return []PodSpec{ps}
60	}
61	
62	// SeccompType is the profile type in force for container, in Trivy's order:
63	// the container's securityContext, then the pod's, then the container
64	// annotation. Empty when none is set. doc is the workload the pod spec belongs
65	// to: the annotation sits on the metadata next to the pod spec, which the spec
66	// node alone does not reach.
67	func SeccompType(doc *yaml.Node, spec PodSpec, container *yaml.Node) string {
68		if t := seccompTypeOf(container); t != "" {
69			return t
70		}
71		if t := seccompTypeOf(spec.Spec); t != "" {
72			return t
73		}
74		path, ok := podSpecPaths[Scalar(doc, "kind")]
75		if !ok {
76			return ""
77		}
78		// The pod's metadata is the sibling of the pod spec: "spec" becomes "metadata".
79		meta := append(append([]string(nil), path[:len(path)-1]...), "metadata")
80		podMeta := follow(doc, meta)
81		if podMeta == nil {
82			return ""
83		}
84		_, annotations, ok := Entry(podMeta, "annotations")
85		if !ok {
86			return ""
87		}
88		return Scalar(annotations, seccompAnnotationPrefix+Scalar(container, "name"))
89	}
90	
91	// seccompTypeOf reads securityContext.seccompProfile.type of a container or a
92	// pod spec.
93	func seccompTypeOf(n *yaml.Node) string {
94		if n == nil {
95			return ""
96		}
97		_, sc, ok := Entry(n, "securityContext")
98		if !ok {
99			return ""
100		}
101		_, profile, ok := Entry(sc, "seccompProfile")
102		if !ok {
103			return ""
104		}
105		return strings.TrimSpace(Scalar(profile, "type"))
106	}
107	
108	// follow walks keys down from n, resolving aliases, and returns nil when the
109	// path is not there.
110	func follow(n *yaml.Node, keys []string) *yaml.Node {
111		for _, key := range keys {
112			if n == nil {
113				return nil
114			}
115			_, v, ok := Entry(n, key)
116			if !ok {
117				return nil
118			}
119			n = v
120		}
121		return n
122	}
